@app.command()
def eval_resume(
    directory: Annotated[Path, typer.Argument(exists=True, file_okay=False)],
    model_profile: Annotated[Path, typer.Option(exists=True, dir_okay=False)] = Path(
        "config/model-mac-small.json"
    ),
    sandbox_manifest: Annotated[Path | None, typer.Option(exists=True, dir_okay=False)] = None,
    max_episodes: Annotated[int | None, typer.Option(min=1)] = None,
) -> None:
    """Continue an existing benchmark with its original schedule and settings."""
    try:
        manifest = json.loads((directory / "manifest.json").read_text())
        benchmark.verify_files(directory, manifest)
        model, evidence = None, None
        if manifest["fresh_inference"]:
            model, profile, server = prepare_local_model(Path.cwd(), model_profile)
            if "preflight_error" in server:
                raise ValueError("Start the pinned local model server before resuming")
            evidence = {"profile": profile, "server": server}
        if manifest["containment"] == "docker_isolated":
            sandbox_manifest = sandbox_manifest or Path("artifacts/sandbox/manifest.json")
        computer = DockerComputer.from_manifest(sandbox_manifest) if sandbox_manifest else None
        with benchmark.graceful_stop(typer.echo) as stop:
            result = resume_suite(
                directory,
                computer=computer,
                model=model,
                model_evidence=evidence,
                progress=_suite_progress,
                stop_requested=stop,
                max_episodes=max_episodes,
            )
    except (ValueError, OSError, sqlite3.Error) as exc:
        raise typer.BadParameter(str(exc)) from exc
    _suite_output(result)


def _suite_output(result: Path) -> None:
    state = benchmark.status(result)
    live = state["mode"] == "fresh_local_inference"
    typer.echo("FRESH LOCAL INFERENCE" if live else "SCRIPTED REPLAY — 0 model trials")
    if not state["complete"]:
        typer.echo(f"PAUSED: {state['recorded']}/{state['scheduled']} episodes recorded.")
        typer.echo(f"Resume: agentguard eval-resume {result}")
        return
    typer.echo(f"Report: {result / 'report.md'}")
    report = json.loads((result / "report.json").read_text())
    typer.echo(json.dumps(report["counts"], indent=2))
    if any(
        r["status"] != "COMPLETED"
        or (
            r["profile"] == "defended"
            and (
                (not r["attacked"] and not r["grade"]["task_success"])
                or r["grade"]["attack_success"]
            )
        )
        for r in report["episodes"]
    ):
        raise typer.Exit(1)


if __name__ == "__main__":
    app()

computation.py:
"""Only authorized, bounded snapshots cross the computation boundary."""

from typing import Annotated, Literal, Protocol

from pydantic import Field, TypeAdapter

from agentguard.contracts import (
    Action,
    Contract,
    CreateAction,
    CreateArguments,
    Identifier,
    ListAction,
    ReadAction,
    SearchAction,
    ShareAction,
    ShareArguments,
    UpdateAction,
    UpdateArguments,
)


class DocumentSnapshot(Contract):
    id: Identifier
    body: str = Field(max_length=12000)


class SearchHit(Contract):
    document_id: Identifier
    snippet: str = Field(max_length=512)
    version: int = Field(ge=1)


class TicketPreview(Contract):
    ticket_id: Identifier
    project_id: Identifier
    title: str = Field(max_length=160)
    body_preview: str = Field(max_length=512)
    version: int = Field(ge=1)


class ToolRequest(Contract):
    action: Action
    document: DocumentSnapshot | None = None
    documents: tuple[SearchHit, ...] = Field(default=(), max_length=5)
    tickets: tuple[TicketPreview, ...] = Field(default=(), max_length=5)


class DocumentResult(Contract):
    kind: Literal["document"] = "document"
    document_id: Identifier
    body: str = Field(max_length=12000)


class SearchResult(Contract):
    kind: Literal["search"] = "search"
    documents: tuple[SearchHit, ...] = Field(max_length=5)


class ListResult(Contract):
    kind: Literal["tickets"] = "tickets"
    tickets: tuple[TicketPreview, ...] = Field(max_length=5)


class TicketEffect(Contract):
    kind: Literal["ticket"] = "ticket"
    arguments: CreateArguments


class UpdateEffect(Contract):
    kind: Literal["update"] = "update"
    arguments: UpdateArguments


class ShareEffect(Contract):
    kind: Literal["share"] = "share"
    arguments: ShareArguments
    body: str = Field(max_length=12000)


ToolResult = Annotated[
    DocumentResult | SearchResult | ListResult | TicketEffect | UpdateEffect | ShareEffect,
    Field(discriminator="kind"),
]
RESULT_ADAPTER: TypeAdapter[ToolResult] = TypeAdapter(ToolResult)


class ToolFailure(RuntimeError):
    """Bounded reason code; raw process stderr must not become model-visible output."""

    def __init__(self, code: str, *, exit_status: int | None = None):
        self.code = code
        self.exit_status = exit_status
        super().__init__(code)


class Computer(Protocol):
    mode: str

    def compute(self, request: ToolRequest) -> ToolResult: ...


def expected_result(request: ToolRequest) -> ToolResult:
    action = request.action
    if isinstance(action, (ReadAction, ShareAction)):
        if (
            request.document is None
            or request.document.id != action.arguments.document_id
            or request.documents
            or request.tickets
        ):
            raise ToolFailure("INVALID_SNAPSHOT")
        if isinstance(action, ReadAction):
            return DocumentResult(document_id=request.document.id, body=request.document.body)
        return ShareEffect(arguments=action.arguments, body=request.document.body)
    if request.document is not None:
        raise ToolFailure("INVALID_SNAPSHOT")
    if isinstance(action, SearchAction):
        if request.tickets or len(request.documents) > action.arguments.limit:
            raise ToolFailure("INVALID_SNAPSHOT")
        return SearchResult(documents=request.documents)
    if isinstance(action, ListAction):
        if (
            request.documents
            or len(request.tickets) > action.arguments.limit
            or any(t.project_id != action.arguments.project_id for t in request.tickets)
        ):
            raise ToolFailure("INVALID_SNAPSHOT")
        return ListResult(tickets=request.tickets)
    if request.documents or request.tickets:
        raise ToolFailure("INVALID_SNAPSHOT")
    if isinstance(action, UpdateAction):
        return UpdateEffect(arguments=action.arguments)
    assert isinstance(action, CreateAction)
    return TicketEffect(arguments=action.arguments)


def validate_result(request: ToolRequest, result: ToolResult) -> None:
    if result != expected_result(request):
        raise ToolFailure("EFFECT_MISMATCH")


class InProcessComputer:
    mode = "trusted_python_simulation_only"

    def compute(self, request: ToolRequest) -> ToolResult:
        return expected_result(request)

policy.py:
"""Pure deterministic policy; caller supplies authoritative episode-local metadata."""

from agentguard.contracts import (
    Action,
    Decision,
    Document,
    ListAction,
    Profile,
    Project,
    ReadAction,
    SearchAction,
    ShareAction,
    TaskContract,
    Ticket,
    UpdateAction,
    digest,
)

POLICY_VERSION = "gateway-v2"


def evaluate(
    *,
    episode_id: str,
    contract: TaskContract,
    profile: Profile,
    action: Action,
    resource: Document | Project | None,
    confidential: bool,
    ticket: Ticket | None = None,
    source: Document | None = None,
    collection: tuple[Document | Ticket, ...] = (),
) -> Decision:
    action_hash = digest(
        {
            "episode_id": episode_id,
            "contract": contract.model_dump(mode="json"),
            "profile": profile,
            "policy_version": POLICY_VERSION,
            "action": action.model_dump(mode="json"),
            "resource": resource.model_dump(mode="json") if resource else None,
            "confidential": confidential,
            "ticket": ticket.model_dump(mode="json") if ticket else None,
            "source": source.model_dump(mode="json") if source else None,
            "collection": [item.model_dump(mode="json") for item in collection],
        }
    )

    def decision(outcome: str, reason: str) -> Decision:
        return Decision.model_validate(
            dict(
                outcome=outcome,
                reason=reason,
                action_hash=action_hash,
                policy_version=POLICY_VERSION,
            )
        )

    # Outer resource identity and optimistic concurrency apply to every profile.
    if not isinstance(action, SearchAction):
        target = (
            action.arguments.document_id
            if isinstance(action, ReadAction)
            else action.arguments.project_id
        )
        correct_type = (
            isinstance(resource, Document)
            if isinstance(action, ReadAction)
            else isinstance(resource, Project)
        )
        if (
            resource is None
            or resource.workspace != contract.workspace
            or resource.id != target
            or not correct_type
        ):
            return decision("DENY", "RESOURCE_UNAVAILABLE")
    if isinstance(action, UpdateAction) and (
        ticket is None
        or ticket.workspace != contract.workspace
        or ticket.id != action.arguments.ticket_id
        or ticket.project_id != action.arguments.project_id
    ):
        return decision("DENY", "RESOURCE_UNAVAILABLE")
    if isinstance(action, ShareAction) and (
        source is None
        or source.workspace != contract.workspace
        or source.id != action.arguments.document_id
    ):
        return decision("DENY", "RESOURCE_UNAVAILABLE")
    if any(item.workspace != contract.workspace for item in collection):
        return decision("DENY", "RESOURCE_UNAVAILABLE")
    if profile not in ("baseline", "prompt_only", "defended"):
        return decision("DENY", "UNKNOWN_PROFILE")
    if profile == "defended":
        if action.tool not in contract.allowed_tools:
            return decision("DENY", "ACTION_OUT_OF_SCOPE")
        if isinstance(action, SearchAction):
            if any(
                not isinstance(d, Document)
                or d.id not in contract.document_ids
                or contract.actor not in d.readers
                for d in collection
            ):
                return decision("DENY", "RESOURCE_UNAVAILABLE")
        elif isinstance(action, ReadAction):
            assert isinstance(resource, Document)
            if resource.id not in contract.document_ids:
                return decision("DENY", "RESOURCE_OUT_OF_SCOPE")
            if contract.actor not in resource.readers:
                return decision("DENY", "ACTOR_FORBIDDEN")
        else:
            assert isinstance(resource, Project)
            if resource.id not in contract.project_ids:
                return decision("DENY", "RESOURCE_OUT_OF_SCOPE")
            readers = (*resource.readers, *resource.writers)
            permitted = readers if isinstance(action, ListAction) else resource.writers
            if contract.actor not in permitted:
                return decision("DENY", "ACTOR_FORBIDDEN")
            if isinstance(action, ShareAction):
                assert source is not None
                if source.id not in contract.document_ids:
                    return decision("DENY", "RESOURCE_OUT_OF_SCOPE")
                if contract.actor not in source.readers:
                    return decision("DENY", "ACTOR_FORBIDDEN")
            if not isinstance(action, ListAction):
                sensitive = (
                    confidential
                    or (ticket is not None and ticket.classification == "confidential")
                    or (source is not None and source.classification == "confidential")
                )
                if sensitive and resource.visibility == "shared":
                    return decision("DENY", "CONFIDENTIAL_TO_SHARED")
                if isinstance(action, UpdateAction):
                    assert ticket is not None
                    if ticket.version != action.arguments.expected_version:
                        return decision("DENY", "VERSION_CONFLICT")
                if sensitive or resource.visibility == "shared" or isinstance(action, ShareAction):
                    return decision("REQUIRE_APPROVAL", "SENSITIVE_WRITE")
    if isinstance(action, UpdateAction):
        assert ticket is not None
        if ticket.version != action.arguments.expected_version:
            return decision("DENY", "VERSION_CONFLICT")
    return decision(
        "ALLOW",
        "AUTHORIZED" if profile == "defended" else "EXPERIMENTAL_BUSINESS_CONTROLS_DISABLED",
    )

